/** Alternate engine study. Exact FEM coordinates generated by export_fem.py. */
import {makeScene2D,Line,Txt,Node,Circle} from '@motion-canvas/2d';
import {all,easeInOutCubic,tween,waitFor} from '@motion-canvas/core';
import fem from '../data.json';
type Vec=[number,number];
const SCALE=155;
const toScreen=(p:Vec):Vec=>[(p[0]-2.8)*194,(1.7-p[1])*194];
const interpolate=(segment:(typeof fem.segments)[number],fraction:number):Vec[] =>
  segment.original.map((p,i)=>toScreen([
    p[0]+SCALE*fraction*segment.displacement[i][0],
    p[1]+SCALE*fraction*segment.displacement[i][1],
  ] as Vec));
const shades=['#6FE1CE','#6FE1CE','#6FE1CE','#6FE1CE'];
export default makeScene2D(function* (view){
  view.fill('#0B131C');
  const root=new Node({});
  view.add(root);
  const header=new Txt({text:'¿DÓNDE CAMBIA LA CURVATURA?',y:-455,fontSize:43,fill:'#F4F3EE',opacity:0});
  const kicker=new Txt({text:'MECÁNICA ESTRUCTURAL / ESTUDIO VISUAL',y:-515,fontSize:21,fill:'#ACB8C3',opacity:0});
  root.add(header);root.add(kicker);
  const shapes=fem.segments.map((part,i)=>{
    const l=new Line({points:interpolate(part,0),stroke:shades[i],lineWidth:9,lineCap:'round',opacity:0});
    root.add(l);return l;
  });
  const location=()=>interpolate(fem.segments[3],0).at(-1) as Vec;
  const x0=location()[0],y0=location()[1];
  const force=new Line({points:[[x0,y0],[x0+155,y0]],stroke:'#F7AE76',lineWidth:8,
                        endArrow:true,arrowSize:18,opacity:0});
  root.add(force);
  yield* all(header.opacity(1,.6),kicker.opacity(1,.6),...shapes.map(v=>v.opacity(1,1.2)));
  yield* waitFor(1.0);
  yield* force.opacity(1,.5);
  yield* waitFor(.8);
  yield* tween(4.5,t=>{
    const f=easeInOutCubic(t);
    shapes.forEach((line,i)=>line.points(interpolate(fem.segments[i],f)));
    const joint=interpolate(fem.segments[3],f).at(-1) as Vec;
    force.points([[joint[0],joint[1]],[joint[0]+155,joint[1]]]);
  });
  yield* waitFor(1);
  yield* all(force.opacity(0,.55),...shapes.slice(1).map(x=>x.opacity(.12,.75)));
  const point=fem.segments[0];
  const left=shapes[0];
  const originalScale=left.scale();
  // Focus on the very same computed column, while the others recede.
  yield* all(...shapes.slice(1).map(x=>x.opacity(0,1.1)),left.scale(1.35,1.1));
  const fraction=fem.inflection_t;
  const ind=Math.max(1,Math.min(point.original.length-2,Math.round(fraction*(point.original.length-1))));
  const p=interpolate(point,1)[ind];
  const zero=new Circle({x:p[0],y:p[1],width:42,height:42,
                         stroke:'#C9B6FF',lineWidth:4,opacity:0});
  root.add(zero);
  const zeroText=new Txt({text:'INFLEXIÓN',fill:'#C9B6FF',fontSize:32,
    x:p[0]+240,y:p[1]-32,opacity:0});
  root.add(zeroText);
  yield* all(zero.opacity(1,.8),zeroText.opacity(1,.8));
  yield* waitFor(2.6);
  yield* all(zero.opacity(0,.5),zeroText.opacity(0,.5));
  // Build signed M(z) about the undeformed member line; same values as ManimGX.
  const axis=new Line({points:point.original.map(p=>toScreen(p as Vec)),
                       stroke:'#F4F3EE',lineWidth:4,opacity:0});
  root.add(axis);
  yield* all(axis.opacity(1,.8),left.opacity(.18,.8));
  const base=toScreen(point.original[0] as Vec);
  const top=toScreen(point.original.at(-1) as Vec);
  const zm=top[1]*fraction+base[1]*(1-fraction);
  const momentNeg=new Line({points:[[base[0],base[1]],[base[0]-175,base[1]],[base[0],zm]],
      stroke:'#EE8A86',fill:'#EE8A8640',closed:true,lineWidth:4,opacity:0});
  const momentPos=new Line({points:[[base[0],zm],[base[0]+126,top[1]],[top[0],top[1]]],
      stroke:'#EFD18F',fill:'#EFD18F40',closed:true,lineWidth:4,opacity:0});
  root.add(momentNeg);root.add(momentPos);
  yield* momentNeg.opacity(1,1.2);
  yield* momentPos.opacity(1,1.2);
  const formula=new Txt({text:'CURVATURA = 0  ⇔  MOMENTO = 0',
    y:450,fontSize:34,fill:'#F4F3EE',opacity:0});
  root.add(formula);
  yield* formula.opacity(1,.5);
  yield* waitFor(6.1);
});
